int dlq_put(const char *dir, const struct msg *m, const char *reason) {
    char tmp[PATH_MAX], final[PATH_MAX];
    snprintf(tmp, sizeof tmp, "%s/.%ld.tmp", dir, (long)getpid());
    FILE *f = fopen(tmp, "w");
    fprintf(f, "dest=%s reason=%s attempts=%d ts=%ld\n",
            m->dest, reason, m->attempts, (long)time(NULL));
    fwrite(m->body, 1, m->len, f);
    fsync(fileno(f)); fclose(f);                 /* data on disk before publish */
    snprintf(final, sizeof final, "%s/%ld.msg", dir, (long)m->seq);
    return rename(tmp, final);                   /* atomic: reader never sees a partial */
}
